3	namespace App\Providers\Filament;
4	
5	use Filament\Http\Middleware\Authenticate;
6	use Filament\Http\Middleware\AuthenticateSession;
7	use Filament\Http\Middleware\DisableBladeIconComponents;
8	use Filament\Http\Middleware\DispatchServingFilamentEvent;
9	use App\Filament\Pages\Dashboard;
10	use Filament\Panel;
11	use Filament\PanelProvider;
12	use Filament\Support\Colors\Color;
13	use Filament\Support\Enums\MaxWidth;
14	use Filament\Widgets;
15	use Illuminate\Cookie\Middleware\AddQueuedCookiesToResponse;
16	use Illuminate\Cookie\Middleware\EncryptCookies;
17	use Illuminate\Foundation\Http\Middleware\VerifyCsrfToken;
18	use Illuminate\Routing\Middleware\SubstituteBindings;
19	use Illuminate\Session\Middleware\StartSession;
20	use Illuminate\View\Middleware\ShareErrorsFromSession;
21	use Filament\View\PanelsRenderHook;
22	
23	class AdminPanelProvider extends PanelProvider
24	{
25	    public function panel(Panel $panel): Panel
26	    {
27	        return $panel
28	            ->default()
29	            ->id('admin')
30	            ->path('admin')
31	            ->login()
32	            ->passwordReset()
33	            ->colors([
34	                'primary' => Color::Amber,
35	            ])
36	            ->viteTheme('resources/css/filament/admin/theme.css')
37	            ->maxContentWidth(MaxWidth::Full)
38	            ->discoverResources(in: app_path('Filament/Resources'), for: 'App\\Filament\\Resources')
39	            ->discoverPages(in: app_path('Filament/Pages'), for: 'App\\Filament\\Pages')
40	            ->pages([
41	                Dashboard::class,
42	            ])
43	            ->discoverWidgets(in: app_path('Filament/Widgets'), for: 'App\\Filament\\Widgets')
44	            ->widgets([
45	                // Widgets\AccountWidget::class,
46	            ])
47	            ->renderHook(
48	                PanelsRenderHook::CONTENT_START,
49	                fn (): \Illuminate\Contracts\View\View => view('filament.leaderboard-announcement'),
50	            )
51	            ->middleware([
52	                EncryptCookies::class,
53	                AddQueuedCookiesToResponse::class,
54	                StartSession::class,
55	                AuthenticateSession::class,
56	                ShareErrorsFromSession::class,
57	                VerifyCsrfToken::class,
58	                SubstituteBindings::class,
59	                DisableBladeIconComponents::class,
60	                DispatchServingFilamentEvent::class,
61	            ])
62	            ->authMiddleware([
63	                Authenticate::class,
64	            ]);
65	    }
66	}
